def get_earth_path(xe, ye, dire):
    if dire == 'R':
        return [(xe + i, ye) for i in range(101)]
    elif dire == 'L':
        return [(xe - i, ye) for i in range(101)]
    elif dire == 'U':
        return [(xe, ye + i) for i in range(101)]
    else:
        return [(xe, ye - i) for i in range(101)]

def get_asteroid_path(xa, ya, dira):
    if dira == 'R':
        return [(xa + i, ya) for i in range(101)]
    elif dira == 'L':
        return [(xa - i, ya) for i in range(101)]
    elif dira == 'U':
        return [(xa, ya + i) for i in range(101)]
    else:
        return [(xa, ya - i) for i in range(101)]

def earliest_collision(earth_path, asteroid_paths):
    for asteroid_path in asteroid_paths:
        for time in range(1, 101):
            if earth_path[time] in asteroid_path:
                return time
    return "SAFE"

def main():
    T = int(input())
    for _ in range(T):
        xe, ye, dire = input().split()
        N = int(input())
        asteroids = [list(map(int, input().split())) for _ in range(N)]

        earth_path = get_earth_path(int(xe), int(ye), dire)
        asteroid_paths = [get_asteroid_path(xa, ya, dira) for xa, ya, dira in asteroids]

        print(earliest_collision(earth_path, asteroid_paths))

if __name__ == "__main__":
    main()

