def factorize(n):
    factors = defaultdict(int)
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            factors[i] += 1
            n //= i
    if n > 1:
        factors[n] += 1
    return factors

def lcm(a, b):
    return a * b // gcd(a, b)

def get_divisors(factors):
    divisors = [1]
    for p, e in factors.items():
        div = p
        for _ in range(e):
            div *= p
            divisors.append(div)
    return sorted(divisors)

